function run(args) {
  if (args.some(x => x.startsWith('--'))) return { code: 2, error: 'unknown option' };
  if (args.length !== 1 || !args[0].trim()) return { code: 2, error: 'one nonempty value required' };
  return { code: 0, output: args[0].trim().toUpperCase() };
}
module.exports = { run };

