2	'use strict';
3	
4	// 安装后环境的完整包验证：npm pack 真实 tarball → 隔离 prefix 全局安装 →
5	// 在安装产物上执行宿主生命周期与三加固功能面断言。
6	// 与 CI 的 npm-install-matrix-smoke.cjs（pack→install→--help）互补：
7	// files 白名单漏文件只有安装环境才能暴露（repo 内测试有全部文件）。
8	//
9	// phase: all(默认) | package | lifecycle | negative | heal
10	// 多轮测评用法：轮1 package+lifecycle；轮2 negative+幂等；轮3 heal（drift→detect→自愈）。
11	
12	const fs = require('node:fs');
13	const os = require('node:os');
14	const path = require('node:path');
15	const { spawnSync } = require('node:child_process');
16	const { runNpmChecked } = require('./lib/npm-cli.cjs');
17	
18	const repoRoot = path.resolve(__dirname, '..');
19	const CHECKS = [];
20	
21	function pass(id, detail) {
22	  CHECKS.push(id);
23	  console.log(`  ✓ ${id}${detail ? `: ${detail}` : ''}`);
24	}
25	
26	function fail(id, detail) {
27	  console.error(`  ✗ ${id}: ${detail}`);
28	  console.error(`FAIL: 用例 ${id} 未通过（已通过 ${CHECKS.length} 项）`);
29	  process.exitCode = 1;
30	  throw new Error(`verification-case-failed:${id}`);
31	}
32	
33	function assert(id, condition, detail) {
34	  if (condition) {
35	    pass(id, detail);
36	    return;
37	  }
38	  fail(id, detail);
39	}
40	
41	// HOME 隔离：init 会写全局 developer profile（os.homedir() 下）；不隔离会
42	// 污染执行验证的机器的真实 profile（name/hosts 被改写）。main() 创建隔离
43	// home 后，所有经 run() 的子进程统一继承。
44	let isolatedHomeDir = null;
45	
46	function run(command, args, options = {}) {
47	  const env = { ...(options.env || process.env) };
48	  if (isolatedHomeDir) {
49	    env.HOME = isolatedHomeDir;
50	  }
51	  return spawnSync(command, args, {
52	    cwd: options.cwd,
53	    encoding: 'utf8',
54	    env,
55	    stdio: options.stdio || 'pipe',
56	    windowsHide: true,
57	  });
58	}
59	
60	function runOk(id, command, args, options = {}) {
61	  const result = run(command, args, options);
62	  assert(
63	    id,
64	    !result.error && result.status === 0,
65	    `exit=${result.status} ${String(result.stderr || result.error || '').split('\n')[0].slice(0, 160)}`,
66	  );
67	  return result;
68	}
69	
70	function createGitRepo(dir) {
71	  fs.mkdirSync(dir, { recursive: true });
72	  run('git', ['init', '-q'], { cwd: dir });
73	  run('git', ['symbolic-ref', 'HEAD', 'refs/heads/main'], { cwd: dir });
74	  run('git', ['config', 'user.name', 'Package Verify'], { cwd: dir });
75	  run('git', ['config', 'user.email', 'verify@example.com'], { cwd: dir });
76	  // 隔离宿主全局 hooks / excludesfile（避免 commit 触发生成 graphify-out 等噪声）。
77	  const disabledHooks = path.join(dir, '.githooks-disabled');
78	  fs.mkdirSync(disabledHooks, { recursive: true });
79	  run('git', ['config', 'core.hooksPath', disabledHooks], { cwd: dir });
80	  run('git', ['config', 'core.excludesfile', path.join(dir, '.gitignore-nonexistent')], { cwd: dir });
81	  fs.writeFileSync(path.join(dir, 'README.md'), '# verify fixture\n');
82	  run('git', ['add', '.'], { cwd: dir });
83	  run('git', ['commit', '-q', '-m', 'fixture'], { cwd: dir });
